import{_ as a,o as s,c as i,a5 as t}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"raisim::DeformableObject::Material","description":"","frontmatter":{"title":"raisim\\\\:\\\\:DeformableObject\\\\:\\\\:Material","editLink":false,"outline":[2,3]},"headers":[],"relativePath":"api/raisim/DeformableObject/Material.md","filePath":"api/raisim/DeformableObject/Material.md"}'),n={name:"api/raisim/DeformableObject/Material.md"};function l(o,e,p,r,d,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="page-title" tabindex="-1">raisim::DeformableObject::Material <a class="header-anchor" href="#page-title" aria-label="Permalink to &quot;raisim::DeformableObject::Material {#page-title}&quot;">​</a></h1><p><code>struct</code> · <code>#include &lt;raisim/object/deformable/DeformableObject.hpp&gt;</code></p><p>Material and solver parameters.</p><h2 id="public-attributes" tabindex="-1">Public attributes <a class="header-anchor" href="#public-attributes" aria-label="Permalink to &quot;Public attributes {#public-attributes}&quot;">​</a></h2><h3 id="totalmass" tabindex="-1">totalMass <a class="header-anchor" href="#totalmass" aria-label="Permalink to &quot;totalMass {#totalmass}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> totalMass</span></span></code></pre></div><p>Total mass (kg). Positive. It is lumped onto the particles in proportion to the triangle area around each particle (one third of every incident triangle); a particle that belongs to no triangle receives the average share. Objects without triangles split it evenly, and filled meshes lump it by volume (see <a href="./MeshParticleOptions.html#mode-2">MeshParticleOptions::Mode::Filled</a>).</p><h3 id="distancecompliance" tabindex="-1">distanceCompliance <a class="header-anchor" href="#distancecompliance" aria-label="Permalink to &quot;distanceCompliance {#distancecompliance}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> distanceCompliance</span></span></code></pre></div><p>XPBD distance compliance. 0 is rigid, larger values are softer. Negative keeps backwards compatibility by using 1 / distanceStiffness.</p><h3 id="distancestiffness" tabindex="-1">distanceStiffness <a class="header-anchor" href="#distancestiffness" aria-label="Permalink to &quot;distanceStiffness {#distancestiffness}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> distanceStiffness</span></span></code></pre></div><p>Legacy stiffness parameter. Prefer distanceCompliance for new code.</p><h3 id="bendcompliance" tabindex="-1">bendCompliance <a class="header-anchor" href="#bendcompliance" aria-label="Permalink to &quot;bendCompliance {#bendcompliance}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bendCompliance</span></span></code></pre></div><p>Bending compliance (1/(N m)): the inverse of the bending modulus D of the surface. 0 is rigid, larger values fold more easily. Negative disables bending unless bendStiffness is positive. For an isotropic plate of thickness t, D = youngsModulus * t^3 / (12 (1 - poissonRatio^2)). The bending energy is quadratic in the curvature change from the rest shape, so curved rest shapes (shells, closed meshes) keep their shape.</p><h3 id="bendstiffness" tabindex="-1">bendStiffness <a class="header-anchor" href="#bendstiffness" aria-label="Permalink to &quot;bendStiffness {#bendstiffness}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bendStiffness</span></span></code></pre></div><p>Bending modulus D (N m), used as 1 / bendCompliance when bendCompliance is negative. A positive value enables automatic adjacent-triangle bending constraints.</p><h3 id="youngsmodulus" tabindex="-1">youngsModulus <a class="header-anchor" href="#youngsmodulus" aria-label="Permalink to &quot;youngsModulus {#youngsmodulus}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> youngsModulus</span></span></code></pre></div><p>Young&#39;s modulus in Pa. If positive, the mesh is a continuous isotropic elastic material with this modulus and poissonRatio (co-rotated linear elasticity: linear elasticity in a frame that rotates with the material), in place of the mesh-edge distance constraints and distanceCompliance. An object with tetrahedra (<a href="./../World.html#adddeformablevolume">World::addDeformableVolume()</a>, or a filled mesh, see <a href="./MeshParticleOptions.html#mode-2">MeshParticleOptions::Mode::Filled</a>) is an elastic solid; otherwise the triangles form a membrane of the given thickness (plane stress). The extra distance constraints (struts, <a href="./../DeformableObject.html#adddistanceconstraint">addDistanceConstraint()</a>) get the compliance L / (E A) with the cross-sectional area A: with the default A = thickness * L, 1 / (E thickness) at every length, a zero-length weld included.</p><h3 id="poissonratio" tabindex="-1">poissonRatio <a class="header-anchor" href="#poissonratio" aria-label="Permalink to &quot;poissonRatio {#poissonratio}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> poissonRatio</span></span></code></pre></div><p>Poisson&#39;s ratio of the membrane or solid (see youngsModulus), in (-1, 0.5). Close to 0.5 a solid is nearly incompressible.</p><h3 id="thickness" tabindex="-1">thickness <a class="header-anchor" href="#thickness" aria-label="Permalink to &quot;thickness {#thickness}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> thickness</span></span></code></pre></div><p>Membrane thickness (m), and the default cross-sectional area thickness * L of the extra distance constraints.</p><h3 id="crosssectionarea" tabindex="-1">crossSectionArea <a class="header-anchor" href="#crosssectionarea" aria-label="Permalink to &quot;crossSectionArea {#crosssectionarea}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> crossSectionArea</span></span></code></pre></div><p>Cross-sectional area of the extra distance constraints. If positive, it overrides thickness * L.</p><h3 id="damping" tabindex="-1">damping <a class="header-anchor" href="#damping" aria-label="Permalink to &quot;damping {#damping}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> damping</span></span></code></pre></div><p>Stiffness-proportional (Rayleigh) damping time (s), nonnegative. Every distance and bending constraint resists its rate of change with a viscous force equal to damping times its elastic stiffness (integrated implicitly), so a vibration mode of angular frequency w gets the damping ratio damping * w / 2: fast, stiff modes are damped more than slow ones. A rigid constraint (zero compliance) loses its whole rate. Rigid motion is not damped. Ignored in the PBD solver mode. Use airDrag for mass-proportional damping.</p><h3 id="airdrag" tabindex="-1">airDrag <a class="header-anchor" href="#airdrag" aria-label="Permalink to &quot;airDrag {#airdrag}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> airDrag</span></span></code></pre></div><p>Air drag rate (1/s), nonnegative. Every particle velocity decays as exp(-airDrag * t), so a free particle under gravity g approaches the terminal speed |g| / airDrag. 0 disables drag.</p><h3 id="collisionradius" tabindex="-1">collisionRadius <a class="header-anchor" href="#collisionradius" aria-label="Permalink to &quot;collisionRadius {#collisionradius}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">double</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> collisionRadius</span></span></code></pre></div><p>Collision sphere radius of each particle (m). Positive.</p><h3 id="iterations" tabindex="-1">iterations <a class="header-anchor" href="#iterations" aria-label="Permalink to &quot;iterations {#iterations}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iterations</span></span></code></pre></div><p>Constraint solver iterations per substep (nonnegative).</p><h3 id="substeps" tabindex="-1">substeps <a class="header-anchor" href="#substeps" aria-label="Permalink to &quot;substeps {#substeps}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> substeps</span></span></code></pre></div><p>Substeps per world step (positive). Deformables whose particles touch step together, with the largest substep count among them.</p><h3 id="solvermode" tabindex="-1">solverMode <a class="header-anchor" href="#solvermode" aria-label="Permalink to &quot;solverMode {#solvermode}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SolverMode solverMode</span></span></code></pre></div><p>Constraint projection scheme.</p><h3 id="selfcollision" tabindex="-1">selfCollision <a class="header-anchor" href="#selfcollision" aria-label="Permalink to &quot;selfCollision {#selfcollision}&quot;">​</a></h3><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> selfCollision</span></span></code></pre></div><p>Collide the particles of this object with each other, except pairs that already overlap in the rest shape, so that a folded cloth rests on itself. Costs a neighbor search every step.</p>',52)])])}const g=a(n,[["render",l]]);export{u as __pageData,g as default};
